// Package fmdata embeds the foxess_modbus register maps (design D-021):
// generated by tools/fmimport/fmimport.py from
// https://github.com/nathanmarlor/foxess_modbus (MIT, © 2021
// nathanmarlor; full notice in THIRD_PARTY_NOTICES.md, source commit in
// the data's source block). They are a *tentative* mapping source: below
// our verified profiles and the cloud schema, never write authority
// (C-008).
package fmdata

import (
	_ "embed"
	"encoding/json"
	"regexp"
	"sort"
	"sync"
)

//go:embed foxess_modbus.json
var raw []byte

// Source is the provenance of the embedded data.
type Source struct {
	Repo    string `json:"repo"`
	Commit  string `json:"commit"`
	Date    string `json:"date"`
	License string `json:"license"`
	Notice  string `json:"notice"`
}

// Version is one generation of a connection type. MaxManagerVersion is
// upstream's threshold ("" = latest); it does not hold on the reference
// KH10, so callers choose the generation from the registers that answer.
type Version struct {
	MaxManagerVersion *string `json:"max_manager_version"`
	Inv               string  `json:"inv"`
	Map               string  `json:"map"`
}

// Connection is one connection type (AUX = RS485, LAN).
type Connection struct {
	Connection   string    `json:"connection"`
	RegisterType string    `json:"register_type"`
	Versions     []Version `json:"versions"`
	// InvalidRanges are never read; IndividualRanges are read one
	// register at a time (upstream's SpecialRegisterConfig).
	InvalidRanges    [][2]int `json:"invalid_ranges"`
	IndividualRanges [][2]int `json:"individual_ranges"`
}

// Profile is one model family.
type Profile struct {
	Model       string       `json:"model"`
	Pattern     string       `json:"pattern"`
	Connections []Connection `json:"connections"`
	re          *regexp.Regexp
}

// Entity is one serialized foxess_modbus entity. Addresses of a 32-bit
// value are listed low word first; Scale multiplies the raw value.
type Entity struct {
	Type      string   `json:"type"`
	Key       string   `json:"key"`
	Name      string   `json:"name"`
	Addresses []int    `json:"addresses"`
	Scale     *float64 `json:"scale"`
	Signed    *bool    `json:"signed"`
	// Values are a select entity's options (raw value → label).
	Values map[string]string `json:"values"`
}

// Map is one generation's entities.
type Map []Entity

// Entity returns the first entity with the key (sensors precede
// numbers/selects of the same key in upstream's sort, which is what
// reads want).
func (m Map) Entity(key string) (Entity, bool) {
	for _, e := range m {
		if e.Key == key {
			return e, true
		}
	}
	return Entity{}, false
}

// Data is the whole import.
type Data struct {
	Source   Source         `json:"source"`
	Profiles []Profile      `json:"profiles"`
	Maps     map[string]Map `json:"maps"`
}

var (
	once sync.Once
	data *Data
)

// Load parses the embedded data once. The data is generated and tested,
// so a parse failure is a build defect and panics.
func Load() *Data {
	once.Do(func() {
		var d Data
		if err := json.Unmarshal(raw, &d); err != nil {
			panic("fmdata: embedded foxess_modbus.json: " + err.Error())
		}
		for i := range d.Profiles {
			d.Profiles[i].re = regexp.MustCompile(d.Profiles[i].Pattern)
		}
		data = &d
	})
	return data
}

// MatchModel returns the first profile whose pattern matches the model
// string (upstream's list order: specific patterns come first).
func (d *Data) MatchModel(model string) (Profile, bool) {
	for _, p := range d.Profiles {
		if p.re.MatchString(model) {
			return p, true
		}
	}
	return Profile{}, false
}

// Map returns a generation's map by key ("KH_PRE133-HOLDING").
func (d *Data) Map(key string) (Map, bool) {
	m, ok := d.Maps[key]
	return m, ok
}

// Block is one register read: Count registers from Addr.
type Block struct{ Addr, Count int }

// maxGap is the largest run of unneeded registers a merged block may
// span (reading a few extra registers beats another round trip).
const maxGap = 8

// Invalid reports whether an address is in a connection's invalid ranges.
func Invalid(a int, invalid [][2]int) bool { return inRanges(a, invalid) }

func inRanges(a int, rs [][2]int) bool {
	for _, r := range rs {
		if a >= r[0] && a <= r[1] {
			return true
		}
	}
	return false
}

// PlanReads turns the needed addresses into block reads that respect a
// connection's special registers: invalid addresses are never read (nor
// spanned), individual-read addresses are read one at a time, blocks
// never exceed maxCount.
func PlanReads(addrs []int, invalid, individual [][2]int, maxCount int) []Block {
	seen := map[int]bool{}
	var as []int
	for _, a := range addrs {
		if !seen[a] && !inRanges(a, invalid) {
			seen[a] = true
			as = append(as, a)
		}
	}
	sort.Ints(as)
	var out []Block
	for _, a := range as {
		if n := len(out); n > 0 && !inRanges(a, individual) && !inRanges(out[n-1].Addr, individual) {
			last := &out[n-1]
			end := last.Addr + last.Count // next unread address
			if a-end <= maxGap && a-last.Addr+1 <= maxCount && !spansInvalid(end, a, invalid) {
				last.Count = a - last.Addr + 1
				continue
			}
		}
		out = append(out, Block{Addr: a, Count: 1})
	}
	return out
}

// spansInvalid reports whether any address in [lo, hi) is invalid.
func spansInvalid(lo, hi int, invalid [][2]int) bool {
	for _, r := range invalid {
		if r[0] < hi && r[1] >= lo {
			return true
		}
	}
	return false
}
